      updatedAnswers[questionId] = answer;
      return { ...prevForm, answers: updatedAnswers };
    });
  };

  return (
    <FeedbackContext.Provider value={{ feedbackForm, handleAnswerChange }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
```
