#include <pigpio.h>

int main() {
    // Initialize the pigpio library
    gpioInitialize();

    // Set the mode of GPIO pin 12 to output
    gpioSetup(12, GPIO_OUTPUT);

    // Set the initial state of GPIO pin 12 to low
    gpioWrite(12, GPIO_LOW);

    // Run indefinitely and perform a toggle every second
    while (1) {
        // Toggle the state of GPIO pin 12
        gpioWrite(12, gpioRead(12) ? GPIO_HIGH : GPIO_LOW);
        delay(1000);
    }

    // Clean up before exiting
    gpioFinalize();
    return 0;
}
